void test_FR_036_01(void)
{
    motion_sample_t sample;
    motion_processor_status_t status;

    status = motion_processor_process(0, 0, 0, 0U, &sample);
    TEST_ASSERT_EQUAL_INT(MOTION_PROCESSOR_STATUS_CALIBRATING, status);

    /* Complete calibration with a zero-motion baseline and start the event window. */
    status = motion_processor_process(0, 0, 0, APP_MOTION_CALIBRATION_DURATION_MS, &sample);
    TEST_ASSERT_EQUAL_INT(MOTION_PROCESSOR_STATUS_OK, status);
    TEST_ASSERT_TRUE(sample.is_calibrated);

    /* Pick the smallest raw magnitude that reaches the configured braking threshold. */
    const int32_t threshold_millig = (int32_t)APP_MOTION_SUDDEN_BRAKING_THRESHOLD_MILLIG;
    const int32_t raw_magnitude =
        (threshold_millig * (int32_t)APP_MOTION_SENSITIVITY_LSB_PER_G + 999) / 1000;
    const int16_t raw_y = (int16_t)(-raw_magnitude);

    status = motion_processor_process(
        0,
        raw_y,
        0,
        APP_MOTION_CALIBRATION_DURATION_MS + APP_MOTION_EVENT_WINDOW_MS,
        &sample);

    TEST_ASSERT_EQUAL_INT(MOTION_PROCESSOR_STATUS_OK, status);
    TEST_ASSERT_EQUAL_INT(MOTION_EVENT_SUDDEN_BRAKING, sample.event);
}
